import React, { useEffect, useRef } from "react";
import * as d3 from "d3";

interface LatestChartWidgetProps {
  data: { timestamp: number; value: number }[]; // x = time
  width?: number;
  height?: number;
  strokeColor?: string;
  title?: string;
}

export const ChartWidget: React.FC<LatestChartWidgetProps> = ({
  data,
  width = 300,
  height = 200,
  strokeColor = "#1e88e5",
  title
}) => {
  const svgRef = useRef<SVGSVGElement | null>(null);

  useEffect(() => {
    if (!svgRef.current || data.length === 0) return;

    const svg = d3.select(svgRef.current);
    svg.selectAll("*").remove(); // Clear if rerendering

    const margin = { top: 20, right: 20, bottom: 30, left: 35 };
    const chartWidth = width - margin.left - margin.right;
    const chartHeight = height - margin.top - margin.bottom;

    const g = svg.append("g")
      .attr("transform", `translate(${margin.left},${margin.top})`);

    const x = d3
      .scaleTime()
      .domain(d3.extent(data, d => new Date(d.timestamp)) as [Date, Date])
      .range([0, chartWidth]);

    const y = d3
      .scaleLinear()
      .domain([0, d3.max(data, d => d.value) ?? 10])
      .range([chartHeight, 0]);

    const line = d3
      .line<{ timestamp: number; value: number }>()
      .x(d => x(new Date(d.timestamp)))
      .y(d => y(d.value))
      .curve(d3.curveMonotoneX);

    g.append("path")
      .datum(data)
      .attr("fill", "none")
      .attr("stroke", strokeColor)
      .attr("stroke-width", 2)
      .attr("d", line);

    g.append("g")
      .attr("transform", `translate(0,${chartHeight})`)
      .call(d3.axisBottom(x).ticks(4));

    g.append("g").call(d3.axisLeft(y).ticks(5));
  }, [data, width, height, strokeColor]);

  return (
    <div style={{ textAlign: "center" }}>
      {title && <div style={{ fontWeight: 600, marginBottom: 4 }}>{title}</div>}
      <svg ref={svgRef} width={width} height={height}></svg>
    </div>
  );
};
